mapper.select:
SELECT x.workspace_code AS workspace_code, COUNT(DISTINCT x.user_id) AS member_count FROM ( SELECT m.workspace_code AS workspace_code, m.user_id AS user_id FROM platform_workspace_member m WHERE m.source = 'DIRECT' AND m.is_deleted = 0 AND m.workspace_code IN #{code}
UNION ALL
SELECT wd.workspace_code AS workspace_code, ud.user_id AS user_id FROM platform_workspace_dept wd JOIN system_dept root ON root.id = wd.dept_id AND root.is_deleted = 0 JOIN system_dept sub ON (sub.id = root.id OR sub.path LIKE CONCAT(root.path, root.id, '/%')) AND sub.is_deleted = 0 JOIN system_user_dept ud ON ud.dept_id = sub.id AND ud.is_deleted = 0 WHERE wd.is_deleted = 0 AND wd.workspace_code IN #{code} AND NOT EXISTS ( SELECT 1 FROM platform_workspace_member ex WHERE ex.workspace_code = wd.workspace_code AND ex.user_id = ud.user_id AND ex.source = 'EXCLUDED' AND ex.is_deleted = 0 ) ) x JOIN system_user u ON u.id = x.user_id AND u.is_deleted = 0 AND u.status = 'ENABLED' GROUP BY x.workspace_code
